import { readFileSync } from "node:fs";

interface Account {
  id: string;
  region: string;
}

export function loadAccounts(path: string): Account[] {
  const parsed = JSON.parse(readFileSync(path, "utf8"));
  return parsed.accounts.map((a: Account) => ({
    id: a.id.toUpperCase(),
    region: a.region.trim(),
  }));
}
